SELECT DISTINCT ?italianWord ?pos ?definition
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?wholeEntry ontolex:canonicalForm [ ontolex:writtenRep ?wholeWr ] .
    FILTER(STR(?wholeWr) = "edificio")
    ?wholeEntry ontolex:sense ?wholeSense .

    ?partSense lexinfo:partMeronym ?wholeSense .

